window.RP_SESSION={"id":"S-d7618fb1e719","messages":[{"id":"RP-0295831","time":"2026-09-22T14:28:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"음···.","characters":["P-b6d81d634c6e"]},{"id":"RP-0295832","time":"2026-09-22T14:29:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그러니까 이건, 마리우스가 일행들과 함께 탑으로 여정을 떠나기 약 이틀 전 쯤의 시간입니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0295833","time":"2026-09-22T14:31:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"마리우스는 어째 곰곰히 걱정이 있다며 살짝 숨을 내뱉고 있고···. 정말 오랜만에 입에 담배를 물었습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0295834","time":"2026-09-22T14:32:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"스트레칭을 쭉 피고, 문 상태로 가볍게 불을 피우고자 투박하게 툭툭 마찰해냅니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0295835","time":"2026-09-22T14:32:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!모닥불","characters":["P-b6d81d634c6e"]},{"id":"RP-0295836","time":"2026-09-22T14:32:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"모닥불에 불씨가 옮겨 붙습니다.\n따뜻한 온기가 피어오릅니다.\n\n ♩ https://youtu.be/3GNyTB6p6i0?si=4L6Rg34M-gtWRqUj","characters":[]},{"id":"RP-0295837","time":"2026-09-22T14:33:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"마리우스가 입에 문 것을 모닥불에 가져다대고, 천천히 숨을 마시다, 뱉어냅니다.\n\n퓨후우우우.","characters":["P-b6d81d634c6e"]},{"id":"RP-0295838","time":"2026-09-22T14:34:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"뽀얀 연기가 천천히 일렁이고. 연이어 마리우스도 안정되는 것을 느낍니다. 이번만 피는 거로 결정하죠···. 꿈도 뒤숭숭하겠다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0295839","time":"2026-09-22T14:35:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"옆에 놓인 육포를 집어, 부시럭, 한 입에 넣습니다. 톡톡 가볍게 흔들어 재를 떨어트리고.","characters":["P-b6d81d634c6e"]},{"id":"RP-0295840","time":"2026-09-22T14:36:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"꾸우우욱. 마리우스가 이윽고 불을 꺼트리고, 다시 육포를 집어먹습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0295841","time":"2026-09-22T14:37:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"신경이 좀 나아졌어요. 나른나른하네요.","characters":["P-b6d81d634c6e"]},{"id":"RP-0295842","time":"2026-09-22T14:47:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"담배핀다","characters":[]},{"id":"RP-0295843","time":"2026-09-22T18:45:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-b6d81d634c6e"]},{"id":"RP-0295844","time":"2026-09-22T18:45:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"한대 정도야 뭐···.","characters":["P-b6d81d634c6e"]},{"id":"RP-0295845","time":"2026-09-22T18:48:00+09:00","room":"RP","name":"샤를로타 롯테","profile":"샤를로타 롯테","identity":"unresolved","type":"dialogue","body":"남편 닮아가네 이러다가 우락부락 해지겠다","characters":[]},{"id":"RP-0295846","time":"2026-09-22T18:58:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"ㅇ거 칭찬인가요 저주인가요","characters":["P-b6d81d634c6e"]},{"id":"RP-0295847","time":"2026-09-22T21:13:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"unresolved","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-0295848","time":"2026-09-22T21:13:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
